```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::{http_client, state_rw};

struct Node;

fn encode(s: &str) -> String {
    let mut out = String::new();
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        // Enrichment fetch (approved grant). The result is deliberately ignored
        // so it cannot affect the output; transport failure is a value, not a trap.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            encode(&published.date)
        );
        let _ = http_client::fetch(&url);

        let mut recorded: u32 = 0;
        if published.published {
            for id in &published.considered {
                state_rw::put(id, "seen");
                recorded += 1;
            }
        }

        RunReport {
            date: published.date,
            recorded,
        }
    }
}

export!(Node);
```

The input has no text field, so the enrichment query uses its `date`, percent-encoded. The fetch result is discarded and uses `fetch`, so a transport failure can't change the output. Ids are marked seen only when `published` is true, and `recorded` counts them, so it is never negative.

